</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include<bits/stdc++.h>
using namespace std;
long long n;
vector<long long> b(20,0);

long long dfs(long long x, int sum) {
    long long num = x / b[sum];
    long long rem = x % b[sum];
    if (rem == 0) return num * sum;
    long long left = dfs(rem, sum-1);
    long long right = sum + dfs(b[sum]-rem, sum-1);
    return num * sum + min(left, right);
}

int main() {
    cin >> n;
    for (int i=1; i<=17; i++) b[i] = b[i-1]*10ll + 1ll;
    string s = to_string(n);
    int m = s.length();
    cout << dfs(n, m+2) << endl;
    return 0;
}
